// hmacHex returns the hex HMAC-SHA256 of the concatenated parts, keyed with secret.
func hmacHex(secret string, parts ...[]byte) string {
	m := hmac.New(sha256.New, []byte(secret))
	for _, p := range parts {
		m.Write(p)
	}
	return hex.EncodeToString(m.Sum(nil))
}

// signTimestamped returns the signature of "<t>.<payload>" keyed with secret, where t is Unix seconds.
func signTimestamped(secret string, t int64, payload []byte) string {
	return hmacHex(secret, []byte(strconv.FormatInt(t, 10)+"."), payload)
