func TestSign(t *testing.T) {
	// HMAC-SHA256("key", "The quick brown fox jumps over the lazy dog")
	const want = "f7bc83f430538424b13298e6aa6fb143ef4d59a14946175997479dbc2d1a3cd8"
	if got := webhooks.Sign("key", []byte("The quick brown fox jumps over the lazy dog")); got != want {
		t.Fatalf("Sign = %s", got)
	}
}

// refSig is the v1 signature of a payload sent at unix seconds at, computed without the package under test.
func refSig(secret string, at int64, payload []byte) string {
	m := hmac.New(sha256.New, []byte(secret))
	fmt.Fprintf(m, "%d.", at)
	m.Write(payload)
	return hex.EncodeToString(m.Sum(nil))
}

func TestSignatureHeader(t *testing.T) {
	body := []byte(`{"id":"evt_1"}`)
	now := time.Unix(1_700_000_000, 0)
	h := webhooks.SignatureHeader([]string{"whsec_new", "whsec_old"}, now, body)
	want := fmt.Sprintf("t=%d,v1=%s,v1=%s", now.Unix(), refSig("whsec_new", now.Unix(), body), refSig("whsec_old", now.Unix(), body))
	if h != want {
		t.Fatalf("SignatureHeader = %s, want %s", h, want)
	}
	for _, secret := range []string{"whsec_new", "whsec_old"} {
		if err := webhooks.Verify(body, h, []string{secret}, 0, now); err != nil {
			t.Errorf("Verify with %s: %v", secret, err)
		}
	}
	if err := webhooks.Verify(body, h, []string{"whsec_other"}, 0, now); !errors.Is(err, webhooks.ErrSignatureMismatch) {
		t.Errorf("Verify with another secret = %v, want ErrSignatureMismatch", err)
	}
}

func TestVerify(t *testing.T) {
	body := []byte(`{"id":"evt_1","type":"invoice.paid"}`)
	now := time.Unix(1_700_000_000, 0)
	ts := now.Unix()
	cases := []struct {
		name      string
		payload   []byte
		header    string
		secrets   []string
		tolerance time.Duration
		want      error
	}{
		{name: "valid", header: fmt.Sprintf("t=%d,v1=%s", ts, refSig("whsec_a", ts, body)), secrets: []string{"whsec_a"}},
		{name: "spaces, unknown v0 and any order", header: fmt.Sprintf(" v0=abc , v1=%s ,  t = %d ", refSig("whsec_a", ts, body), ts), secrets: []string{"whsec_a"}},
		{name: "second of several secrets", header: fmt.Sprintf("t=%d,v1=%s", ts, refSig("whsec_b", ts, body)), secrets: []string{"whsec_a", "whsec_b"}},
		{name: "a later v1 entry matches", header: fmt.Sprintf("t=%d,v1=%s,v1=%s", ts, refSig("whsec_x", ts, body), refSig("whsec_a", ts, body)), secrets: []string{"whsec_a"}},
		{name: "tolerance 0 means 5 minutes", header: fmt.Sprintf("t=%d,v1=%s", ts-299, refSig("whsec_a", ts-299, body)), secrets: []string{"whsec_a"}},
		{name: "future timestamp within tolerance", header: fmt.Sprintf("t=%d,v1=%s", ts+60, refSig("whsec_a", ts+60, body)), secrets: []string{"whsec_a"}, tolerance: time.Minute},
		{name: "replayed beyond tolerance", header: fmt.Sprintf("t=%d,v1=%s", ts-301, refSig("whsec_a", ts-301, body)), secrets: []string{"whsec_a"}, want: webhooks.ErrTimestampTolerance},
		{name: "future beyond tolerance", header: fmt.Sprintf("t=%d,v1=%s", ts+301, refSig("whsec_a", ts+301, body)), secrets: []string{"whsec_a"}, want: webhooks.ErrTimestampTolerance},
		{name: "custom tolerance", header: fmt.Sprintf("t=%d,v1=%s", ts-11, refSig("whsec_a", ts-11, body)), secrets: []string{"whsec_a"}, tolerance: 10 * time.Second, want: webhooks.ErrTimestampTolerance},
		{name: "wrong secret", header: fmt.Sprintf("t=%d,v1=%s", ts, refSig("whsec_a", ts, body)), secrets: []string{"whsec_b"}, want: webhooks.ErrSignatureMismatch},
		{name: "no secrets", header: fmt.Sprintf("t=%d,v1=%s", ts, refSig("whsec_a", ts, body)), want: webhooks.ErrSignatureMismatch},
		{name: "changed payload", payload: []byte(`{"id":"evt_2"}`), header: fmt.Sprintf("t=%d,v1=%s", ts, refSig("whsec_a", ts, body)), secrets: []string{"whsec_a"}, want: webhooks.ErrSignatureMismatch},
		{name: "signature without the timestamp", header: fmt.Sprintf("t=%d,v1=%s", ts, refSig("whsec_a", ts, body)[:20]), secrets: []string{"whsec_a"}, want: webhooks.ErrSignatureMismatch},
		{name: "empty header", header: "", secrets: []string{"whsec_a"}, want: webhooks.ErrMalformedHeader},
		{name: "pair without =", header: "t=1700000000,v1", secrets: []string{"whsec_a"}, want: webhooks.ErrMalformedHeader},
		{name: "timestamp not an integer", header: "t=abc,v1=x", secrets: []string{"whsec_a"}, want: webhooks.ErrMalformedHeader},
		{name: "empty timestamp", header: "t=,v1=x", secrets: []string{"whsec_a"}, want: webhooks.ErrMalformedHeader},
		{name: "no timestamp", header: fmt.Sprintf("v1=%s", refSig("whsec_a", ts, body)), secrets: []string{"whsec_a"}, want: webhooks.ErrNoTimestamp},
		{name: "no signature", header: fmt.Sprintf("t=%d,v0=abc", ts), secrets: []string{"whsec_a"}, want: webhooks.ErrNoSignature},
		{name: "malformed beats no timestamp", header: "v1=x,oops", secrets: []string{"whsec_a"}, want: webhooks.ErrMalformedHeader},
		{name: "no timestamp beats tolerance", header: "v1=x", secrets: []string{"whsec_a"}, want: webhooks.ErrNoTimestamp},
		{name: "tolerance beats no signature", header: fmt.Sprintf("t=%d", ts-301), secrets: []string{"whsec_a"}, want: webhooks.ErrTimestampTolerance},
		{name: "no signature beats mismatch", header: fmt.Sprintf("t=%d,v1=x", ts), secrets: []string{"whsec_a"}, want: webhooks.ErrSignatureMismatch},
	}
	for _, c := range cases {
		t.Run(c.name, func(t *testing.T) {
			payload := c.payload
			if payload == nil {
				payload = body
			}
			err := webhooks.Verify(payload, c.header, c.secrets, c.tolerance, now)
			if c.want == nil {
				if err != nil {
					t.Fatalf("Verify = %v, want nil", err)
				}
				return
			}
			if !errors.Is(err, c.want) {
				t.Fatalf("Verify = %v, want %v", err, c.want)
			}
		})
	}
}

