	_, _ = e.Store.CreateWebhookEndpoint(store.WebhookEndpoint{OrgID: e.Globex.ID, URL: "https://hooks.globex.example/", Events: []string{"*"}, Secret: "whsec_d", Enabled: true}, now)

	if err := e.Webhooks.Publish(ctx, e.Acme.ID, "customer.created", map[string]string{"id": "cus_1"}); err != nil {
		t.Fatal(err)
	}
	n, err := e.Webhooks.RunDue(ctx)
	if err != nil || n != 1 {
		t.Fatalf("RunDue = %d, %v (only the endpoint for every event wants customer.created)", n, err)
	}
	reqs := e.HTTP.Requests()
	if len(reqs) != 1 || reqs[0].URL != all.URL || reqs[0].Method != http.MethodPost {
		t.Fatalf("requests = %+v", reqs)
	}
	if err := webhooks.Verify(reqs[0].Body, reqs[0].Header.Get("Tally-Signature"), []string{"whsec_a"}, 0, e.Clock.Now()); err != nil {
		t.Fatalf("signature %q: %v", reqs[0].Header.Get("Tally-Signature"), err)
	}
	var body webhooks.Body
	if err := json.Unmarshal(reqs[0].Body, &body); err != nil || body.Type != "customer.created" || reqs[0].Header.Get("Tally-Event-Id") != body.ID {
		t.Fatalf("body = %s (%v)", reqs[0].Body, err)
	}
	ds := e.Store.Deliveries(e.Acme.ID, all.ID)
	if len(ds) != 1 || ds[0].Status != store.DeliverySucceeded || ds[0].Attempts != 1 || ds[0].ResponseStatus != 200 {
		t.Fatalf("deliveries = %+v", ds)
	}

	e.HTTP.Respond = func(r apitest.Request) (int, error) { return http.StatusInternalServerError, nil }
	_ = e.Webhooks.Publish(ctx, e.Acme.ID, "invoice.paid", map[string]string{"invoice_id": "in_1"})
	if n, _ := e.Webhooks.RunDue(ctx); n != 2 {
		t.Fatalf("RunDue = %d, want 2", n)
	}
	for _, ep := range []store.WebhookEndpoint{all, paid} {
		ds := e.Store.Deliveries(e.Acme.ID, ep.ID)
		last := ds[len(ds)-1]
		if last.Status != store.DeliveryFailed || last.ResponseStatus != 500 || last.Error == "" {
			t.Fatalf("delivery to %s = %+v", ep.URL, last)
		}
	}
	if n, _ := e.Webhooks.RunDue(ctx); n != 0 {
		t.Fatalf("a failed delivery was sent again: %d", n)
	}
}

func TestSecretRotation(t *testing.T) {
	e := apitest.New(t)
	ctx := context.Background()
	var ep store.WebhookEndpoint
	e.MustDo(http.StatusCreated, "POST", "/v1/webhook-endpoints", e.Acme.Key, map[string]any{"url": "https://hooks.acme.example/tally", "events": []string{"*"}}, &ep)
	first := ep.Secret

	// send publishes an event, delivers it and returns the request the receiver got.
	send := func() apitest.Request {
		t.Helper()
		if err := e.Webhooks.Publish(ctx, e.Acme.ID, "customer.created", map[string]string{"id": "cus_1"}); err != nil {
			t.Fatal(err)
		}
		if n, err := e.Webhooks.RunDue(ctx); err != nil || n != 1 {
			t.Fatalf("RunDue = %d, %v", n, err)
		}
		reqs := e.HTTP.Requests()
		return reqs[len(reqs)-1]
	}
	// expectSecrets checks that the delivery is signed with exactly these secrets, current first.
	expectSecrets := func(r apitest.Request, secrets ...string) {
		t.Helper()
		want := webhooks.SignatureHeader(secrets, e.Clock.Now(), r.Body)
		if got := r.Header.Get("Tally-Signature"); got != want {
			t.Fatalf("Tally-Signature = %s, want %s", got, want)
		}
	}
	rotate := func() string {
		t.Helper()
		var rotated store.WebhookEndpoint
		r := e.MustDo(http.StatusOK, "POST", "/v1/webhook-endpoints/"+ep.ID+"/rotate-secret", e.Acme.Key, nil, &rotated)
		if !regexp.MustCompile(`^whsec_[0-9a-f]{32}$`).MatchString(rotated.Secret) || rotated.ID != ep.ID {
			t.Fatalf("rotate answered %s", r)
		}
		if _, ok := r.Map(t)["previous_secret"]; ok {
			t.Fatalf("rotate showed the previous secret: %s", r)
		}
		return rotated.Secret
	}

	if r := e.Do("POST", "/v1/webhook-endpoints/we_missing/rotate-secret", e.Acme.Key, nil); r.Code != http.StatusNotFound {
		t.Fatalf("rotate of a missing endpoint = %s", r)
	}

	second := rotate()
	if second == first {
		t.Fatal("rotate kept the secret")
	}
	expectSecrets(send(), second, first)

	e.Clock.Advance(webhooks.SecretOverlap - time.Second)
	expectSecrets(send(), second, first)

	e.Clock.Advance(time.Second)
	expectSecrets(send(), second)

	third := rotate()
	expectSecrets(send(), third, second)
	// Doer sends the deliveries; nil means an HTTP client with a 10 second timeout that does not follow redirects.
	Doer Doer
	// Resolver checks endpoint hosts; nil means net.DefaultResolver.
	Resolver Resolver
}

// Service manages endpoints' URLs and sends deliveries.
type Service struct {
	store    *store.Store
	clock    clock.Clock
	doer     Doer
	resolver Resolver
}

// New returns a Service.
func New(opt Options) *Service {
	s := &Service{store: opt.Store, clock: opt.Clock, doer: opt.Doer, resolver: opt.Resolver}
	if s.clock == nil {
		s.clock = clock.Real{}
	}
	if s.doer == nil {
		s.doer = &http.Client{Timeout: 10 * time.Second, CheckRedirect: func(*http.Request, []*http.Request) error { return http.ErrUseLastResponse }}
	}
	if s.resolver == nil {
		s.resolver = net.DefaultResolver
	}
	return s
}

// EventTypes are the events Tally sends. An endpoint subscribes to some of them, or to "*" for all.
var EventTypes = []string{
		}
		return nil
	})
}

// send POSTs the event to the endpoint and returns the response status and, when it failed, why.
func (s *Service) send(ctx context.Context, ep store.WebhookEndpoint, e store.Event) (int, string) {
	body, err := json.Marshal(Body{ID: e.ID, Type: e.Type, CreatedAt: e.CreatedAt, Data: e.Data})
	if err != nil {
		return 0, err.Error()
	}
	now := s.clock.Now()
	ctx, cancel := context.WithTimeout(ctx, 10*time.Second)
	defer cancel()
	req, err := http.NewRequestWithContext(ctx, http.MethodPost, ep.URL, bytes.NewReader(body))
	if err != nil {
		return 0, err.Error()
	}
	req.Header.Set("Content-Type", "application/json")
	req.Header.Set("User-Agent", "Tally-Webhooks/1.0")
	req.Header.Set("Tally-Event-Id", e.ID)
	req.Header.Set("Tally-Event-Type", e.Type)
	req.Header.Set("Tally-Signature", SignatureHeader(signingSecrets(ep, now), now, body))
	resp, err := s.doer.Do(req)
	if err != nil {
		return 0, err.Error()
	}
	defer resp.Body.Close()
	_, _ = io.Copy(io.Discard, io.LimitReader(resp.Body, 64<<10))
	if resp.StatusCode < 200 || resp.StatusCode > 299 {
		return resp.StatusCode, fmt.Sprintf("the endpoint answered %d", resp.StatusCode)

